function resolveIcon(airlineIata) {
  if (!airlineIata) return FALLBACK_ICON;
  const id = `${airlineIata}_logo`;
  return KNOWN_ICONS.has(id) ? id : FALLBACK_ICON;
}

let payload;
if (route) {
  const airlineIata = route.airline && route.airline.iata ? route.airline.iata.toLowerCase() : null;
  const from = route.origin ? (route.origin.iata_code || route.origin.icao_code) : '???';
  const to = route.destination ? (route.destination.iata_code || route.destination.icao_code) : '???';
  payload = {
    text: `${nearest.callsign} ${from}-${to}`,
    durationMs: 5000,
    textCase: 'asTyped',
    icon: resolveIcon(airlineIata)
  };
} else {
  payload = {
    text: nearest.callsign,
    durationMs: 5000,
    textCase: 'asTyped',
    icon: FALLBACK_ICON
  };
}
return [{ json: payload }];
